scwin.vScrenID = "ULDINS05000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    if ($c.stf.compareFromToDate2(edt_pISUR_APPL_SDATE, edt_pISUR_APPL_EDATE) == false) {
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05000_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.listCorpInfoInquiry" + "&{P}ISUR_APPL_SDATE=" + edt_pISUR_APPL_SDATE.getValue() + "&{P}ISUR_APPL_EDATE=" + edt_pISUR_APPL_EDATE.getValue() + "&{P}ACTIV_YN=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}BZ_REG_NO=" + txb_pBZ_REG_NO.getValue() + "&{P}CORP_REG_NO=" + txb_pCORP_REG_NO.getValue();
    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};



/********************************************** 
 * 함수명   : ins_readCorpInfoSimbol
 * 설명       : 심볼 조회한다. 
 ***********************************************/
scwin.ins_readCorpInfoSimbol = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05000_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpInfoSimbol" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue() + "&{P}COM_SYMBL=" + txb_ISUR_SYMBL.getValue();
    dts_Simbol.DataID = encodeURI(url);
    dts_Simbol.reset();
};

/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 발행기관 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(isurcd) {
    dts_histList.removeAll();
    dts_detail.removeAll();
    if (isurcd == "") return;


    // 회사명 변경내역 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS25000_CHGLIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.listDownloadIsurChgInfoInquiry" + "&{P}param01=" + isurcd + "&{P}param02=" + isurcd;
    dts_histList.DataID = encodeURI(url);
    dts_histList.reset();

    // 발행기관 상세
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05000_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpDetailInfoView" + "&{P}param01=" + isurcd;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
    scwin.ins_readCorpInfoUserInfo(isurcd);
};



/********************************************** 
 * 함수명   : ins_readCorpInfoUserInfo
 * 설명       : 발행기관 담당자 리스트
 ***********************************************/
scwin.ins_readCorpInfoUserInfo = function(isurcd) {
    dts_UsrList.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ISSUEID_LIST_21320_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpDetailUserInfoView" + "&{P}param01=" + isurcd;
    dts_UsrList.DataID = encodeURI(url);
    dts_UsrList.reset();
};


/********************************************** 
 * 함수명   : getSqlChg
 * 설명       : 회사명 변경내역 sql 조건 만들기
 ***********************************************/
scwin.getSqlChg = function(isurcd) {
    var sql = "1 = 1 \n";
    //발행기관코드 조건 만들기. 
    sql += "   AND A.ISUR_CD BETWEEN '" + isurcd + "' AND '" + isurcd + "' \n";
    return sql;
};



/********************************************** 
 * 함수명   : fn_Use_Empower_stk
 * 설명       : 화면 권한 조정한다.
 ***********************************************/
scwin.fn_Use_Empower_stk = function(SPOT_ISU_TRD_MKT_TP_CD, CNTR_ISO_CD, LIST_STAT_CD) {
    $c.stf.setObjectValue(ckb_FLAG1, "N");
    $c.stf.setObjectValue(ckb_FLAG2, "N");

    /*
    		SPOT_ISU_TRD_MKT_TP_CD -- 시장구분  01213 주권상장법인여부
    '1' stk_lst_corp_yn   유가증권시장 
    '2' kosaq_lst_corp_yn  코스닥시장 
    '6' mkt3_lst_corp_yn   코넥스시장 
    */
    //2002.01.14 송기명 대리 요청으로 채권상장법인에 대한  설정을 주석처리함.
    if ((SPOT_ISU_TRD_MKT_TP_CD == "1" || SPOT_ISU_TRD_MKT_TP_CD == "2" || SPOT_ISU_TRD_MKT_TP_CD == "6") && LIST_STAT_CD == "Y") {
        img_CNTRCD.src = "../img/btn_search_d.gif";
        img_CNTRCD.setDisabled(true);
        img_BANK.src = "../img/btn_search_d.gif";
        img_BANK.setDisabled(true);
        cmb_ACTIV_YN.setDisabled(true);
        txb_COM_NM.setDisabled(true);
        txb_COM_ABBRV.setDisabled(true);
        txb_COM_ENG_NM.setDisabled(true);
        txb_COM_ENG_ABBRV.setDisabled(true);
        txb_CORP_REG_NO.setDisabled(true);
        txb_BZ_REG_NO.setDisabled(true);
        txb_DTL_ADDR.setDisabled(true);
        img_ZIPCD.src = "../img/btn_search_d.gif";
        img_ZIPCD.setDisabled(true);
        txb_CEO_NM.setDisabled(true);
        txb_HPAGE.setDisabled(true);
        txb_CORP_TEL_NO.setDisabled(true);
        cmb_ACNTCLS_MM1.setDisabled(true);
        cmb_ACNTCLS_MM2.setDisabled(true);
        cmb_ACNTCLS_MM3.setDisabled(true);
        cmb_ACNTCLS_MM4.setDisabled(true);
        cmb_ACNTCLS_MM5.setDisabled(true);
        cmb_ACNTCLS_MM6.setDisabled(true);
        cmb_ACNTCLS_MM7.setDisabled(true);
        cmb_ACNTCLS_MM8.setDisabled(true);
        cmb_ACNTCLS_MM9.setDisabled(true);
        cmb_ACNTCLS_MM10.setDisabled(true);
        cmb_ACNTCLS_MM11.setDisabled(true);
        cmb_ACNTCLS_MM12.setDisabled(true);
        edt_FOUND_DD.setReadOnly(true);
        edt_FOUND_DD.ReadOnlyBackColor = '#b9d4f7';
        img_FOUND_DD.src = "../img/icn_calendar_d.gif";
        img_FOUND_DD.setDisabled(true);
        cmb_TRANSSTK_AGNT_CD.setDisabled(true); // 명의개서기관 
        txb_ISUR_SYMBL.setDisabled(true);
        //cmb_LIST_STAT_CD.enable2 = false; 
        //cmb_SPOT_ISU_TRD_MKT_TP_CD.enable2 =false; 
        cmb_COM_ATTR_TP_CD.setDisabled(true);
        btn_simbol.src = "../img/ins/btn_simbol_d.gif";
        btn_simbol.setDisabled(true);
        btn_save.src = "../img/ins/btn_save_d.gif";
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_isunmchg.src = "../img/ins/btn_isunmchg_d.gif";
        btn_save.setDisabled(true);
        btn_modify.setDisabled(true);
        btn_isunmchg.setDisabled(true);
        $c.stf.setObjectValue(ckb_FLAG1, "Y");
    } else {
        img_CNTRCD.src = "../img/btn_search.gif";
        img_CNTRCD.setDisabled(false);
        img_BANK.src = "../img/btn_search.gif";
        img_BANK.setDisabled(false);
        cmb_ACTIV_YN.setDisabled(false);
        txb_COM_NM.setDisabled(false);
        txb_COM_ABBRV.setDisabled(false);
        txb_COM_ENG_NM.setDisabled(false);
        txb_COM_ENG_ABBRV.setDisabled(false);
        txb_CORP_REG_NO.setDisabled(false);
        txb_BZ_REG_NO.setDisabled(false);
        txb_DTL_ADDR.setDisabled(false);
        img_ZIPCD.src = "../img/btn_search.gif";
        img_ZIPCD.setDisabled(false);
        txb_CEO_NM.setDisabled(false);
        txb_HPAGE.setDisabled(false);
        txb_CORP_TEL_NO.setDisabled(false);
        cmb_ACNTCLS_MM1.setDisabled(false);
        cmb_ACNTCLS_MM2.setDisabled(false);
        cmb_ACNTCLS_MM3.setDisabled(false);
        cmb_ACNTCLS_MM4.setDisabled(false);
        cmb_ACNTCLS_MM5.setDisabled(false);
        cmb_ACNTCLS_MM6.setDisabled(false);
        cmb_ACNTCLS_MM7.setDisabled(false);
        cmb_ACNTCLS_MM8.setDisabled(false);
        cmb_ACNTCLS_MM9.setDisabled(false);
        cmb_ACNTCLS_MM10.setDisabled(false);
        cmb_ACNTCLS_MM11.setDisabled(false);
        cmb_ACNTCLS_MM12.setDisabled(false);
        edt_FOUND_DD.setReadOnly(false);
        edt_FOUND_DD.ReadOnlyBackColor = 'white';
        img_FOUND_DD.src = "../img/icn_calendar.gif";
        img_FOUND_DD.setDisabled(false);
        cmb_TRANSSTK_AGNT_CD.setDisabled(false); // 명의개서기관 
        txb_ISUR_SYMBL.setDisabled(false);
        //cmb_LIST_STAT_CD.enable2 = true; 
        //cmb_SPOT_ISU_TRD_MKT_TP_CD.enable2 =true; 
        cmb_COM_ATTR_TP_CD.setDisabled(false);
        btn_simbol.src = "../img/ins/btn_simbol.gif";
        btn_simbol.setDisabled(false);
        btn_save.src = "../img/ins/btn_save.gif";
        btn_modify.src = "../img/ins/btn_modify.gif";
        btn_isunmchg.src = "../img/ins/btn_isunmchg.gif";
        btn_save.setDisabled(false);
        btn_modify.setDisabled(false);
        btn_isunmchg.setDisabled(false);

        // 국내법인이 아닌 경우 우편번호 팝업금지
        if (CNTR_ISO_CD == "410") {
            img_ZIPCD.src = "../img/btn_search.gif";
            img_ZIPCD.setDisabled(false);
            txb_CORP_REG_NO.setDisabled(false);
            txb_BZ_REG_NO.setDisabled(false);
        } else {
            img_ZIPCD.src = "../img/btn_search_d.gif";
            img_ZIPCD.setDisabled(true);
            txb_CORP_REG_NO.setDisabled(true);
            txb_BZ_REG_NO.setDisabled(true);
        }
    }
    if ($c.stf.getObjectValue(txb_BND_LIST_CORP_YN) == "Y") {
        $c.stf.setObjectValue(ckb_FLAG2, "Y");
    }

    //표준코드 아이디 복수발급 여부 셋팅
    if ($c.stf.getObjectValue(txb_STD_CD_ID_MULT_ISU_YN) == "Y") {
        $c.stf.setObjectValue(ckb_FLAG3, "Y");
    } else {
        $c.stf.setObjectValue(ckb_FLAG3, "N");
    }
};




/********************************************** 
 * 함수명   : fn_Set_Detail
 * 설명       : 국가코드에 따른 설정을 정의한다.
 ***********************************************/
scwin.fn_Set_Detail = function(CNTR_ISO_CD) {
    var CNTR_CD = CNTR_ISO_CD;
    if (CNTR_CD == "410") {
        txb_ADDR.setReadOnly(true);
        txb_ADDR.style.backgroundColor = '#b9d4f7';
        //txb_DTL_ADDR.disabled = true; 
        //	txb_ADDR.background-color = '#b9d4f7';	

    } else {
        txb_ADDR.setReadOnly(false);
        txb_ADDR.style.backgroundColor = '#ffffff';
        //txb_DTL_ADDR.disabled =  false; 

    }
};





/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
    scwin.arrPar[2] = txb_param3.getValue();
    scwin.arrPar[3] = txb_param4.getValue();
    scwin.arrPar[4] = txb_param5.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : ins_register
 * 설명       : 발행기관 등록한다.
 ***********************************************/
scwin.ins_register = function() {
    if (scwin.fn_formCheck() == false) return;
    trs_save.Action = "/CorpInfoAction.do?method=registerCorpInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : ins_modify
 * 설명       : 발행기관 수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    trs_modify.Action = "/CorpInfoAction.do?method=modifyCorpInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst2,I:pInput=dts_detail)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};

/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (!$c.cp.isModified(dts_detail)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }

    //textarea 개행문자제거
    txa_STD_CD_MEMO.text = txa_STD_CD_MEMO.text.replace(/[\r|\n]/g, "");
    if (txb_simbol_chk.getValue() == "F") {
        $c.win.alert("중복된 심볼입니다.");
        return false;
    }
    if (txb_COM_NM.getValue() == "" || txb_COM_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명(한글)"));
        txb_COM_NM.focus();
        return false;
    }
    if (!fn_checkValueNullMaxlength(txb_COM_NM, "발행기관명(한글)")) return false;
    if (txb_COM_ABBRV.getValue() == "" || txb_COM_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명(한글약명)"));
        txb_COM_ABBRV.focus();
        return false;
    }
    if (!fn_checkValueNullMaxlength(txb_COM_ABBRV, "발행기관명(한글약명)")) return false;
    if (txb_COM_ENG_NM.getValue() == "" || txb_COM_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명(영문)"));
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (!fn_checkValueNullMaxlength(txb_COM_ENG_NM, "발행기관명(영문)")) return false;
    if (txb_COM_ENG_ABBRV.getValue() == "" || txb_COM_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명(영문약명)"));
        txb_COM_ENG_ABBRV.focus();
        return false;
    }
    if (!fn_checkValueNullMaxlength(txb_COM_ENG_ABBRV, "발행기관명(영문약명)")) return false;
    if (txb_CNTR_ISO_CD.getValue() == "410") {
        if (txb_CORP_REG_NO.getValue() == "" || txb_CORP_REG_NO.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인등록번호"));
            txb_CORP_REG_NO.focus();
            return false;
        }
        if (txb_BZ_REG_NO.getValue() == "" || txb_BZ_REG_NO.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "사업자등록번호"));
            txb_BZ_REG_NO.focus();
            return false;
        }
    }
    if (txb_CEO_NM.getValue() == "" || txb_CEO_NM.getValue().indexOf(" ") == "") {
        var rn = confirm("대표이사 없이 진행 하시겠습니까?");
        if (rn == 1) {

        } else {
            txb_CEO_NM.focus();
            return false;
        }
    }
    if (!$c.stf.checkMaxLength(txb_CEO_NM, 20, "대표이사")) {
        //txb_COM_ENG_NM.value = "";
        txb_CEO_NM.focus();
        return false;
    }
    /*
    if(txb_CORP_TEL_NO.value =="" || txb_CORP_TEL_NO.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "대표전화번호") );
    	txb_CORP_TEL_NO.focus();
    	return false;
    } 
    */

    if (!$c.stf.checkMaxLength(txb_HPAGE, 200, "홈페이지")) {
        //txb_COM_ENG_NM.value = "";
        txb_HPAGE.focus();
        return false;
    }

    /* 결산월 control */
    var cmb_ChkCnt = 0;
    var tmpCnt = 0;
    var tmpAcntMM = new Array();
    for (var i = 1; i <= 12; i++) {
        if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == "") {
            cmb_ChkCnt = cmb_ChkCnt + 1;
        }
    }
    if (cmb_ChkCnt == 12) {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "결산월"));
        cmb_ACNTCLS_MM1.focus();
        return;
    }
    for (var i = 1; i <= 12; i++) {
        for (var j = 12; j >= 1; j--) {
            if (i != j) {
                if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + j) != "") {
                        if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + j)) {
                            $c.win.alert("동일한 결산월이 존재합니다.\n결산월을 확인해주세요!");
                            return false;
                        }
                    }
                }
            } else {
                if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    tmpAcntMM[tmpCnt] = dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i);
                    tmpCnt = tmpCnt + 1;
                }
            }
        }
    }
    if (cmb_ChkCnt == 11) {
        for (var i = 2; i <= 12; i++) {
            if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD1", dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i));
                dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i, "");
            }
        }
    } else {
        for (var h = 1; h <= 12; h++) {
            dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + h, "");
        }
        for (var k = 1; k <= tmpCnt; k++) {
            dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + k, tmpAcntMM[k - 1]);
        }
    }
    if (!$c.stf.checkMaxLength(txb_BZ_REG_IND_NM, 100, "업종")) {
        //txb_COM_ENG_NM.value = "";
        txb_BZ_REG_IND_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BZ_REG_BZCOND_NM, 100, "업태")) {
        //txb_COM_ENG_NM.value = "";
        txb_BZ_REG_BZCOND_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BFSPLIT_COM_NM, 100, "분할전법인명")) {
        //txb_COM_ENG_NM.value = "";
        txb_BFSPLIT_COM_NM.focus();
        return false;
    }
    if (txb_CNTR_ISO_CD.getValue() == "" || txb_CNTR_ISO_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드"));
        txb_CNTR_ISO_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
        cmb_SPOT_ISU_TRD_MKT_TP_CD.focus();
        return false;
    }
    /*
    if(getObjectValue(cmb_LIST_STAT_CD) == "" ) {
    	alert( getMessageParam("MSG-A005", "상장여부") );
    	cmb_LIST_STAT_CD.focus();
    	return false;
    } 
    */
    if ($c.stf.getObjectValue(cmb_COM_ATTR_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사속성"));
        cmb_COM_ATTR_TP_CD.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ADDR, 200, "주소")) {
        //txb_COM_ENG_NM.value = "";
        txb_ADDR.focus();
        return false;
    }

    //발행기관명(한글), 발행기관명(한글약명), 주소상세 완성형한글 체크
    var urlck = "/CorpInfoAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=processCompleteKoreanCheck";
    urlck += "&outputMessageId=INS_CHECK_CLS_COMPLETE_KOREAN";
    urlck += "&COM_NM=" + $c.stf.getObjectValue(txb_COM_NM);
    urlck += "&COM_ABBRV=" + $c.stf.getObjectValue(txb_COM_ABBRV);
    urlck += "&DTL_ADDR=" + $c.stf.getObjectValue(txb_DTL_ADDR);
    urlck += "&CEO_NM=" + $c.stf.getObjectValue(txb_CEO_NM);
    urlck += "&BZ_REG_IND_NM=" + $c.stf.getObjectValue(txb_BZ_REG_IND_NM);
    urlck += "&BZ_REG_BZCOND_NM=" + $c.stf.getObjectValue(txb_BZ_REG_BZCOND_NM);
    dts_completeKorean.SyncLoad = "true";
    dts_completeKorean.DataID = encodeURI(urlck);
    dts_completeKorean.Reset();
    var msg = '';
    msg += ' 발행기관(한글명, 한글약명, 상세주소, 대표이사, 업종, 업태)';
    msg += '\n\n 한글표기에 문제가 있습니다. 계속 진행하시겠습니까?';
    msg += '\n\n (시스템담당자에게 문의하시기 바랍니다.)';
    if (dts_completeKorean.getTotalRow() > 0) {
        if (!window.confirm(msg)) {
            processGp = '1';
            return false;
        }
    }
};




