scwin.dts_Rst_OnLoadCompleted = function(rowcount) {
    // 발행기관 등록시 결과 값  
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    //alert(RESULT_CONTN); 
    if (RESULT_CONTN == "CORP_REG_NO") {
        $c.win.alert(" 동일한 법인등록번호가 존재합니다.[" + txb_CORP_REG_NO.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "BZ_REG_NO") {
        $c.win.alert(" 동일한 사업자등록번호가 존재합니다.[" + txb_BZ_REG_NO.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "GOVBND_ISUR_CD") {
        $c.win.alert(" 동일한 국채 기관코드가 존재합니다.[" + txb_GOVBND_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "MUNIBND_ISUR_CD") {
        $c.win.alert(" 동일한 지방채 기관코드가 존재합니다.[" + txb_MUNIBND_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "SPECLBND_ISUR_CD") {
        $c.win.alert(" 동일한 특수채 기관코드가 존재합니다.[" + txb_SPECLBND_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "BENFCERT_ISUR_CD") {
        $c.win.alert(" 동일한 수익증권 기관코드가 존재합니다.[" + txb_BENFCERT_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "NEW_ISUR_CD_FAIL") {
        $c.win.alert(" 발행기관 코드 생성시 실패입니다.\n 다시 시도 부탁드립니다.");
    } else if (RESULT_CONTN == "NEW_ISUR_CD") {
        $c.win.alert(" 발행기관코드 중복 체크\n 발행기관코드가 존재합니다.");
    } else {
        $c.win.alert(txb_COM_NM.getValue() + "\n[" + RESULT_CONTN + "] 발행기관 코드 생성되었습니다.");
        //	 ins_search();
        scwin.ins_search();
        scwin.ins_detail(RESULT_CONTN); // 생성된 발행기관 코드로 재조회 

    }
};
