scwin.btn_clearPwd_onclick = function() {
    // 데이터셋 , 
    //화면ID , 
    //03수정 , 
    //0 : 발행기관  1: 표준코드 , 
    //신청ID
    var isurCd = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "ISUR_CD");
    var comNm = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "COM_NM");
    var integUsrId = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "INTEG_USR_ID");
    var userNm = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "CORP_USR_NM");
    var idStatCd = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "ACCSS_LMT_YN");
    var chrgEmail = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "ENCRYP_EMAIL");
    var chrgSms = dts_UsrList.getCellData(dts_UsrList.getRowPosition(), "ENCRYP_CELLPHONE_NO");
    if (integUsrId == "") {
        $c.win.alert("발행기관 담당자 이름을 선택하세요");
        return;
    }
    if (idStatCd != "Y") {
        $c.win.alert("비밀번호 잠금해제는 아이디가 잠김상태일때만 할 수 있습니다.");
        return;
    }
    if (chrgEmail == "") {
        $c.win.alert("메일주소가 없어 안내메일은 발송하지 않습니다.");
    }
    if (chrgSms == "") {
        $c.win.alert("휴대번호가 없어 SMS는 발송하지 않습니다.");
    }
    var msg = userNm + "님의 비밀번호 잠금해제 하시겠습니까?";
    var res = window.confirm(msg);
    if (res) {

        //dts_pwd.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_pwd.insertRow();
        dts_pwd.setCellData(1, "ISUR_CD", isurCd);
        dts_pwd.setCellData(1, "COM_NM", comNm);
        dts_pwd.setCellData(1, "INTEG_USR_ID", integUsrId);
        dts_pwd.setCellData(1, "CORP_USR_NM", userNm);
        dts_pwd.setCellData(1, "ENCRYP_EMAIL", chrgEmail);
        dts_pwd.setCellData(1, "ENCRYP_CELLPHONE_NO", chrgSms);
        trs_pwd.Action = "/ListedCompanyPasswordAction.do?method=executeUserInitPassword" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_pwd.KeyName = "toinb_dataid4";
        trs_pwd.KeyValue = "JSP(I:pInput=dts_pwd)";
        //trs_pwd.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email ;  
        trs_pwd.Post();
    }
};
